/**
 * Shared API contracts. Types here describe the wire format between
 * apps/api and its clients (web, mobile, worker). Keep them framework-free.
 */

/**
 * Response body of `GET /health` on the API. Always HTTP 200 while the process
 * is up; `status` is `degraded` when a dependency (currently the database) is down.
 */
export interface HealthResponse {
  status: 'ok' | 'degraded';
  service: 'api';
  /** ISO-8601 timestamp generated by the server. */
  timestamp: string;
  database: 'up' | 'down';
}
